solution.solution.py:
def type_name(value):
    return type(value).__name__


def whole_number(text):
    return int(float(text))


def average(a, b, c):
    return (a + b + c) / 3

unitTests:
@test("type names")
def _():
    check_eq(type_name(42), "int")
    check_eq(type_name(4.2), "float")
    check_eq(type_name("42"), "str")
    check_eq(type_name(True), "bool")
    check_eq(type_name(None), "NoneType")

@test("text to whole numbers")
def _():
    check_eq(whole_number("42"), 42)
    check(type(whole_number("42")) is int, "42 should become an int")
    check_eq(whole_number("2.75"), 2)
    check(type(whole_number("3.0")) is int, "3.0 should become an int")
    check_eq(whole_number("-7.5"), -7)

@test("averages are floats")
def _():
    check_eq(average(1, 2, 3), 2.0)
    check(type(average(1, 2, 3)) is float, "the average should be a float")
    check_near(average(1, 2, 2), 1.6666666667, 1e-6)

